define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_46.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e183326","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_47.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e183430","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_43.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e183534","topics":[]},{"title":"Opening the gradient Power Distribution Unit (PDU) top tray","shortdesc":"<p class=\"shortdesc\">Open the gradient PDU top tray to do troubleshooting or replacement tasks.<\/p>","href":"t_OpeningTheGradientPDUTopTray_3.html","attributes":{"data-id":"id_2006331"},"menu":{"hasChildren":false},"tocID":"id_2006331-d46e183638","topics":[]},{"title":"Installing the hoist","shortdesc":"<p class=\"shortdesc\">Install the hoist in order to replace components within the Integrated System Cabinet (ISC) and Integrated Cooling Cabinet (ICC).<\/p>","href":"t_InstallingTheHoist_6.html","attributes":{"data-id":"id_2003492"},"menu":{"hasChildren":false},"tocID":"id_2003492-d46e183742","topics":[]},{"title":"Removing the gradient Power Distribution Unit (PDU) top tray","shortdesc":"<p class=\"shortdesc\">Remove the gradient Power Distribution Unit (PDU) top tray from the ISC cabinet.<\/p>","href":"t_RemovingtheGPDU.html","attributes":{"data-id":"id_2033231"},"menu":{"hasChildren":false},"tocID":"id_2033231-d46e183846","topics":[]},{"title":"Installing the gradient Power Distribution Unit (PDU) top tray","shortdesc":"<p class=\"shortdesc\">Install the gradient Power Distribution Unit (PDU) top tray in the ISC cabinet.<\/p>","href":"t_InstallingtheGPDU.html","attributes":{"data-id":"id_2033232"},"menu":{"hasChildren":false},"tocID":"id_2033232-d46e183952","topics":[]},{"title":"Removing the hoist","shortdesc":"<p class=\"shortdesc\">Remove the hoist beam and return it to its storage location.<\/p>","href":"t_RemovingTheHoist_6.html","attributes":{"data-id":"id_2003868"},"menu":{"hasChildren":false},"tocID":"id_2003868-d46e184058","topics":[]},{"title":"Closing the gradient Power Distribution Unit (PDU) top tray","shortdesc":"<p class=\"shortdesc\">Close the gradient PDU top tray after doing troubleshooting or replacement tasks.<\/p>","href":"t_ClosingTheGradientPDUTopTray_3.html","attributes":{"data-id":"id_2006332"},"menu":{"hasChildren":false},"tocID":"id_2006332-d46e184162","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_45.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e184266","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_46.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e184371","topics":[]},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_70.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e184475","topics":[]}]});